{	
	os_tsk_wait(DEI_SS_DELAY_TRIGGER);  	

    if( get_ss_arm() && !get_ss_valet() && !get_rs_gwr() )
	{
//		dei_ss_trigger_start( DEI_SS_TRIGGER_ZONE_SENSOR3 ) ; 
		dei_ss_trigger_start( DEI_SS_TRIGGER_ZONE_DOOR ) ; 
	}    
}	

